const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state=structuredClone(SEED),page='episodes',epId='ep01',tab='shots',assetFilter='全部',query='',zoom=1;
const current=()=>state.episodes.find(e=>e.id===epId)||state.episodes[0];
const shotBy=id=>current().shots.find(s=>s.id===id);
const src=s=>/^(assets\/|\/media\/|data:(image\/(png|jpeg|webp)|audio\/[\w.+-]+|video\/mp4);base64,|blob:)/.test(s||'')?esc(s):'';
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function save(){if(!db){toast('浏览器未允许保存，请导出项目备份');return}const tx=db.transaction('project','readwrite');tx.objectStore('project').put(structuredClone(state),'current');tx.onerror=()=>toast('保存失败，请导出备份以保留内容')}
async function init(){try{db=await new Promise((resolve,reject)=>{let r=indexedDB.open('wanxiang-studio-open-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('project');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});let old=await new Promise(resolve=>{let r=db.transaction('project').objectStore('project').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null)});if(old)state=old;state.episodes.forEach(e=>{e.title=e.title.replace(/^\ufeff第\d+集\s*/, '');e.script=e.script.replace(/^\ufeff/, '')})}catch(e){toast('自动保存不可用，请使用项目备份')}render()}
function go(p){page=p;query='';render();window.scrollTo(0,0)}
function render(){if(!state.episodes.some(e=>e.id===epId))epId=state.episodes[0]?.id;$('#projectName').textContent=state.title+' ▾';$$('#navigation button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent={source:'故事与剧本',episodes:'分集与分镜',assets:'创作资产库',canvas:'制作画布'}[page];$('#app').innerHTML=({episodes:episodesPage,source:sourcePage,assets:assetsPage,canvas:canvasPage}[page])();bindPage()}
function steps(){return `<div class="workflow"><button data-go="source">01 导入故事</button><span class="line"></span><button class="active" data-go="episodes">02 分集与分镜</button><span class="line"></span><button data-go="assets">03 确认创作资产</button><span class="line"></span><button data-go="canvas">04 进入制作画布 ↗</button></div>`}
function episodesPage(){const e=current();return `<section class="hero"><div class="hero-text"><div class="eyebrow">A STORY TAKES SHAPE</div><h1>${esc(state.title)}</h1><p>${esc(state.subtitle)} · 从文字里的世界，到每一个看得见的镜头。</p><div class="metrics"><div class="metric"><b>${state.episodes.length}</b>集剧本</div><div class="metric"><b>${state.episodes.reduce((n,e)=>n+e.shots.length,0)}</b>个分镜</div><div class="metric"><b>${state.assets.length}</b>项创作资产</div></div></div><div class="hero-image"><img src="assets/cover.svg" alt="故事创作示意图"></div></section>${steps()}<div class="content-split"><aside class="episode-list"><div class="section-label"><b>分集目录</b><small>${state.episodes.length} EPISODES</small></div>${state.episodes.map(x=>`<button class="episode-item ${x.id===e.id?'selected':''}" data-ep="${esc(x.id)}"><span class="ep-number">${String(x.number).padStart(2,'0')}</span><span><strong>${esc(x.title)}</strong><small>${x.shots.length?x.shots.length+'个镜头 · '+x.shots.reduce((n,s)=>n+s.duration,0)+'秒':'剧本已导入 · 待拆分镜'}</small></span></button>`).join('')}</aside><section><div class="episode-head"><div><div class="eyebrow">EPISODE ${String(e.number).padStart(2,'0')}</div><h2>${esc(e.title)}</h2><p>${esc(e.summary)}</p></div><div class="actions"><button id="exportEpisode">↓ 导出</button><button class="primary" id="startProduction">开始制作 ↗</button></div></div><div class="tabs"><button data-tab="shots" class="${tab==='shots'?'active':''}">分镜总览 <small>${e.shots.length}</small></button><button data-tab="script" class="${tab==='script'?'active':''}">本集剧本</button><button data-tab="voices" class="${tab==='voices'?'active':''}">配音台词</button><button data-tab="intro" class="${tab==='intro'?'active':''}">本集介绍</button><button data-tab="preview" class="${tab==='preview'?'active':''}">本集预览</button></div>${episodeBody(e)}</section></div>`}
function episodeBody(e){if(tab==='script')return `<div class="panel"><label class="field">本集剧本<textarea class="script-editor" id="episodeScript">${esc(e.script)}</textarea></label><button id="saveScript" class="primary">保存剧本</button> <button id="splitScript">${e.shots.length?'重新拆分为分镜草稿':'拆分为分镜草稿'}</button><div class="notice">按场景和动作段落拆分，保留原始对白。生成的是可编辑草稿，需检查节奏和连续性。</div></div>`;
if(tab==='intro')return `<div class="panel"><label class="field">本集名称<input id="episodeTitle" value="${esc(e.title)}"></label><label class="field">本集介绍<textarea id="episodeSummary">${esc(e.summary)}</textarea></label><button id="saveIntro" class="primary">保存介绍</button></div>`;
if(tab==='voices')return `<div class="panel"><h3>声音时间表</h3><p class="muted">对白按镜头顺序排列。正式配音逐镜导入，音色参考在人物档案中试听。</p>${e.shots.length?e.shots.map((s,i)=>`<div class="voice-row"><div>S${String(i+1).padStart(2,'0')}<br><small>${e.shots.slice(0,i).reduce((n,x)=>n+x.duration,0)}秒起 · ${s.duration}秒</small></div><p>${esc(s.dialogue)}</p><button data-edit-shot="${esc(s.id)}">${s.audio?'查看配音':'导入配音'}</button>${s.audio?`<audio controls src="${src(s.audio)}"></audio>`:''}</div>`).join(''):'本集尚未拆分镜头。'}</div>`;
return `<div class="toolbar"><span>${e.shots.length} 个镜头 · ${e.shots.filter(s=>s.image).length} 张关键帧 · ${e.shots.filter(s=>s.audio).length} 段配音</span><div class="actions"><button id="addShot">＋ 新增镜头</button>${e.shots.length?'':'<button id="splitScript">拆分分镜草稿</button>'}</div></div>${e.shots.length?`<div class="shots">${e.shots.map((s,i)=>`<article class="shot-card" tabindex="0" role="button" aria-label="查看镜头 ${esc(s.title)}" data-edit-shot="${esc(s.id)}"><div class="shot-cover">${s.image?`<img loading="lazy" src="${src(s.image)}" alt="${esc(s.title)}">`:'<div class="placeholder">◇ 等待关键帧</div>'}<span class="shot-badge">S${String(i+1).padStart(2,'0')}</span><span class="shot-duration">${s.duration}s</span></div><div class="shot-content"><div class="shot-title"><h3>${esc(s.title)}</h3><span>↗</span></div><p>${esc(s.description)}</p><div class="shot-foot"><span>${s.image?'● 关键帧已收录':'○ 待生成关键帧'}</span><span>${s.dialogue==='环境声与动作声'?'环境声':s.dialogue.split('\n').filter(Boolean).length+'句台词'} · ${s.audio?'配音已导入':'待配音'}</span></div></div></article>`).join('')}</div>`:`<div class="empty"><div class="symbol">▤</div><h3>从本集剧本，开始拆分镜头</h3><p>先生成分镜草稿，再确认人物形象与场景。每个独立动作对应一张关键帧。</p><button class="primary" id="splitEmpty">拆分分镜草稿 →</button></div>`}`}
function sourcePage(){return `<div class="page-heading"><div><div class="eyebrow">THE BEGINNING OF A STORY</div><h1>让故事，从这里开始</h1><p>上传小说或剧本，整理成集，再一步步长成画面。</p></div></div><div class="source-layout"><div class="panel"><label class="dropzone" id="dropzone"><span style="font-size:34px;color:#819473">⇧</span><strong>拖入小说或剧本</strong><p>或点击选择文件 · TXT / Markdown · 最大 10 MB</p><input hidden type="file" id="storyFile" accept=".txt,.md,.markdown"></label><div class="section-label" style="margin-top:24px"><b>也可以直接粘贴文本</b><small id="fileName">尚未选择文件</small></div><label class="field">项目名称<input id="newTitle" placeholder="为你的故事起个名字"></label><textarea id="storyInput" class="source-paste" placeholder="第01集 雨后的小店&#10;&#10;01-1 小店 内 日&#10;人物：店主&#10;【画面】店主打开窗户，让阳光照进来。&#10;店主：今天也会是好天气。"></textarea><label class="field" style="margin-top:15px">分集方式<select id="splitMode"><option value="heading">按“第X集 / 第X章”标题分集</option><option value="length">按篇幅拆分（约1500字一集）</option></select></label><button class="primary" id="importStory">解析并预览分集 →</button></div><div><div class="panel"><div class="eyebrow">CURRENT PROJECT</div><h2 style="margin-top:12px">${esc(state.title)}</h2><p class="muted">${esc(state.importedName)}</p><div class="metrics"><div class="metric"><b>${state.episodes.length}</b>集</div><div class="metric"><b>${state.assets.length}</b>项资产</div></div><button style="margin-top:20px" data-go="episodes">继续制作当前项目 ↗</button></div><div class="panel"><h3>你的制作顺序</h3><p class="muted" style="font-size:13px;line-height:2.2">01　导入故事，检查分集<br>02　拆分动作镜头，编辑台词<br>03　建立人物、道具与场景档案<br>04　确认新形象，准备独立关键帧<br>05　整集素材带入画布，编排配音</p><div class="notice">导入新故事前可导出当前项目备份；导入预览不会改变现有项目。</div></div></div></div>`}
function assetCategories(){return [...new Set(['人物','道具','场景',...(state.assetCategories||[]),...state.assets.map(a=>a.kind)].filter(k=>typeof k==='string'&&k.trim()&&k!=='全部'))]}
function addAssetCategory(){openModal(`${modalTop('新增资产分类')}<p class="muted">例如：服装、特效、音乐。新增后可在资产档案中选择。</p><label class="field">分类名称<input id="categoryName" maxlength="30" placeholder="输入分类名称" autocomplete="off"></label><p id="categoryError" role="alert" class="category-error"></p><div class="dialog-footer"><button data-close>取消</button><button id="saveCategory" class="primary">创建分类</button></div>`);$('#categoryName').focus();const submit=()=>{const name=$('#categoryName').value.trim().normalize('NFKC');if(!name||name.length>30){$('#categoryError').textContent='请输入1—30字的分类名称';return}if(['全部',...assetCategories()].some(k=>k.normalize('NFKC').toLocaleLowerCase()===name.toLocaleLowerCase())){$('#categoryError').textContent='这个分类已存在，请换一个名称';return}state.assetCategories=[...(state.assetCategories||[]),name];assetFilter=name;query='';save();$('#modal').close();render();toast('已新增分类：'+name)};$('#saveCategory').onclick=submit;$('#categoryName').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submit()}}}
function removeAssetCategory(name){if(['全部','人物','道具','场景'].includes(name)||!assetCategories().includes(name))return;const count=state.assets.filter(a=>a.kind===name).length;openModal(`${modalTop('删除分类 · '+name)}<p>${count?'该分类有 '+count+' 项资产，请选择移入的分类。资产内容和镜头关联都会保留。':'该分类没有资产，删除后将从分类栏移除。'}</p>${count?`<label class="field">资产移入<select id="categoryMoveTo">${assetCategories().filter(k=>k!==name).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')}</select></label>`:''}<div class="dialog-footer"><button data-close>取消</button><button class="delete" id="confirmRemoveCategory">${count?'移动资产并删除分类':'删除分类'}</button></div>`);$('#confirmRemoveCategory').onclick=()=>{const assets=state.assets.filter(a=>a.kind===name),target=$('#categoryMoveTo')?.value;if(assets.length&&(!target||target===name||!assetCategories().includes(target)))return toast('请选择资产移入的分类');state.categoryDeletionHistory??=[];state.categoryDeletionHistory.push({name,deletedAt:new Date().toISOString(),target:target||null,assetIds:assets.map(a=>a.id)});assets.forEach(a=>a.kind=target);state.assetCategories=(state.assetCategories||[]).filter(k=>k!==name);if(assetFilter===name)assetFilter='全部';save();$('#modal').close();render();toast('分类已删除'+(assets.length?'，资产已移入'+target:''))}}
function assetsPage(){let filtered=state.assets.filter(a=>(assetFilter==='全部'||a.kind===assetFilter)&&(`${a.name}${a.description}${a.traits}`.includes(query)));return `<div class="page-heading"><div><div class="eyebrow">A WORLD WITH CONTINUITY</div><h1>创作资产库</h1><p>让每个人、每件信物、每一处风景，在故事里保持一致。</p></div><div class="actions asset-header-actions"><button class="primary" id="addAsset">＋ 新建资产</button></div></div><div class="filterbar asset-filterbar"><div class="asset-category-tabs">${['全部',...assetCategories()].map(t=>`<span class="category-chip ${assetFilter===t?'selected':''}"><button data-filter="${esc(t)}" class="${assetFilter===t?'active':''}">${esc(t)} ${state.assets.filter(a=>t==='全部'||a.kind===t).length}</button>${['全部','人物','道具','场景'].includes(t)?'':`<button class="category-remove" data-remove-category="${esc(t)}" aria-label="删除分类 ${esc(t)}" title="删除分类">×</button>`}</span>`).join('')}<button id="addCategory" class="add-category">＋ 新增分类</button></div><input id="assetSearch" placeholder="搜索资产名称、性格…" value="${esc(query)}" aria-label="搜索资产"></div><div class="asset-grid">${filtered.map(a=>`<article role="button" tabindex="0" class="asset-card" data-asset="${esc(a.id)}">${a.image?`<img src="${src(a.image)}" alt="${esc(a.name)}">`:'<div class="empty">◇</div>'}<div class="body"><span class="tag">${esc(a.kind)}</span><h3 style="margin-top:10px">${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="shot-foot"><span>${esc(a.approval==='已确认'?'● 形象已确认':'○ 形象待确认')}</span><span>${state.episodes.reduce((n,e)=>n+e.shots.filter(s=>s.assetIds.includes(a.id)).length,0)} 镜引用 ↗</span></div></div></article>`).join('')}</div>${filtered.length?'':'<div class="empty">未找到匹配的资产</div>'}`}
function canvasPage(){const e=current(),nodes=state.canvas[e.id];return `<div class="page-heading"><div><div class="eyebrow">FROM STORYBOARD TO SCREEN</div><h1>制作画布</h1><p>关键帧、镜头描述与声音，在这里连成一个故事。</p></div><button id="exportCanvas">↓ 导出画布</button></div><div class="toolbar"><div class="canvas-controls"><select id="canvasEpisode" aria-label="选择画布集数">${state.episodes.map(x=>`<option value="${esc(x.id)}" ${e.id===x.id?'selected':''}>第${x.number}集 · ${esc(x.title)}</option>`).join('')}</select><span>${nodes?.length||0} 个素材节点</span></div><div class="canvas-controls"><button id="zoomOut" aria-label="缩小">−</button><span>${Math.round(zoom*100)}%</span><button id="zoomIn" aria-label="放大">＋</button><button id="arrange">整理布局</button><button class="primary" id="syncCanvas">${nodes?'同步本集素材':'带入本集素材'} ↗</button></div></div>${nodes?.length?`<div class="board-viewport"><div class="board" style="width:${Math.max(...nodes.map(n=>n.x))+360}px;height:${Math.max(...nodes.map(n=>n.y))+480}px;transform:scale(${zoom})"><svg width="100%" height="100%">${e.shots.map(s=>{let nn=nodes.filter(n=>n.shotId===s.id);return nn.slice(1).map((n,i)=>{let p=nn[i];return `<path d="M${p.x+290},${p.y+90} C${p.x+315},${p.y+90} ${n.x-25},${n.y+90} ${n.x},${n.y+90}" fill="none" stroke="#9eae94" stroke-width="1.5"/>`}).join('')}).join('')}</svg>${nodes.map(n=>canvasNode(n)).join('')}</div></div><div class="canvas-hint">拖动卡片标题调整位置 · 横向滚动查看整组素材 · 编辑镜头后点击“同步本集素材”，保留已有布局</div>`:`<div class="empty"><div class="symbol">⌘</div><h3>给本集一个制作空间</h3><p>点击“带入本集素材”，按镜头生成关键帧、描述、配音三类节点。</p><button class="primary" id="createBoard">带入本集素材 →</button></div>`}`}
function canvasNode(n){let s=shotBy(n.shotId);if(!s)return '';let i=current().shots.indexOf(s)+1;return `<div class="canvas-node" style="left:${n.x}px;top:${n.y}px" data-node="${esc(n.id)}"><div class="node-head"><b>S${String(i).padStart(2,'0')} · ${n.type==='image'?'关键帧':n.type==='prompt'?'镜头描述':'配音'}</b><span>⠿</span></div><div class="node-body"><div class="node-kind">${esc(s.title)} · ${s.duration}秒</div>${n.type==='image'?`${s.image?`<img src="${src(s.image)}" alt="${esc(s.title)}">`:'<div class="empty" style="padding:25px">待导入关键帧</div>'}<p>${s.image?'关键帧已收录':'先确认相关资产形象，再准备关键帧。'}</p>`:n.type==='prompt'?`<p style="max-height:150px;white-space:pre-wrap">${esc(s.description)}</p>`:`<p class="dialogue">${esc(s.dialogue)}</p>${s.audio?`<audio controls src="${src(s.audio)}"></audio>`:'<p>○ 台词已带入 · 正式配音待导入</p>'}`}<button data-edit-shot="${esc(s.id)}">${n.type==='image'?'查看 / 更换关键帧':n.type==='prompt'?'编辑镜头':'管理配音'}</button></div></div>`}
function openModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
const modalTop=title=>`<div class="modal-top"><h2>${esc(title)}</h2><button data-close aria-label="关闭">✕</button></div>`;
function editShot(id){const s=shotBy(id);let pendingImage=s.image,pendingAudio=s.audio;openModal(`${modalTop('镜头 · '+s.title)}<div class="detail-grid"><div>${s.image?`<a href="${src(s.image)}" target="_blank"><img class="detail-image" src="${src(s.image)}" alt="${esc(s.title)}"></a>`:'<div class="empty">待导入关键帧</div>'}<div class="inline-actions"><button type="button" id="pickImage">↑ 上传关键帧</button><input type="file" id="shotImage" accept="image/png,image/jpeg,image/webp" hidden><button id="generateFrame">生成关键帧</button><button id="copyPrompt">复制完整提示词</button></div><div class="notice" id="imageStatus">每个独立动作使用独立参考图。新人物或新妆造需先确认。</div><label class="field">关联资产</label><div class="checkboxes">${state.assets.map(a=>`<label><input type="checkbox" name="asset" value="${esc(a.id)}" ${s.assetIds.includes(a.id)?'checked':''}>${esc(a.name)}</label>`).join('')}</div><label class="field">正式配音<input type="file" id="shotAudio" accept="audio/*"></label><div id="audioStatus">${s.audio?`<audio controls src="${src(s.audio)}"></audio>`:'尚未导入本镜配音'}</div><p class="muted" style="font-size:11px">人物参考音色不会自动替代本镜台词音频。上传后仍需审听。</p><button id="removeAudio" class="quiet">移除本镜配音</button></div><div><label class="field">镜头名称<input id="shotTitle" value="${esc(s.title)}"></label><label class="field">建议时长（秒）<input id="shotDuration" type="number" min="1" max="120" value="${s.duration}"></label><label class="field">镜头描述<textarea id="shotDescription" style="min-height:135px">${esc(s.description)}</textarea></label><label class="field">对应台词<textarea id="shotDialogue">${esc(s.dialogue)}</textarea></label><label class="field">完整生成提示词<textarea id="shotPrompt">${esc(s.prompt)}</textarea></label></div></div><div class="dialog-footer"><button id="deleteShot" class="delete">删除镜头</button><button data-close>取消</button><button id="saveShot" class="primary">保存镜头</button></div>`);
$('#pickImage').onclick=()=>$('#shotImage').click();$('#shotImage').onchange=async ev=>{let f=ev.target.files[0];if(!f)return;try{pendingImage=await readMedia(f,'image');$('#imageStatus').textContent='已选择 '+f.name+'，保存后生效'}catch(e){toast(e.message)}};$('#shotAudio').onchange=async ev=>{let f=ev.target.files[0];if(!f)return;try{pendingAudio=await readMedia(f,'audio');$('#audioStatus').innerHTML=`<audio controls src="${src(pendingAudio)}"></audio><small>待审听 · 保存后生效</small>`}catch(e){toast(e.message)}};
$('#removeAudio').onclick=()=>{pendingAudio='';$('#audioStatus').textContent='保存后移除配音'};$('#generateFrame').onclick=()=>{const unapproved=state.assets.filter(a=>$$('input[name="asset"]:checked').some(i=>i.value===a.id)&&a.approval!=='已确认');toast(unapproved.length?'请先在资产库确认关联形象：'+unapproved.map(a=>a.name).join('、'):'出图服务尚未连接，请复制提示词到生成平台，完成后上传关键帧')};$('#copyPrompt').onclick=()=>copy($('#shotPrompt').value||$('#shotDescription').value);$('#saveShot').onclick=()=>{let duration=Number($('#shotDuration').value),title=$('#shotTitle').value.trim();if(!title||!Number.isFinite(duration)||duration<1||duration>120)return toast('请填写镜头名称和1—120秒的时长');Object.assign(s,{title,duration,description:$('#shotDescription').value,dialogue:$('#shotDialogue').value,prompt:$('#shotPrompt').value,image:pendingImage,audio:pendingAudio,assetIds:$$('input[name="asset"]:checked').map(x=>x.value)});save();$('#modal').close();render();toast('镜头已保存')};$('#deleteShot').onclick=()=>{if(!confirm('删除这个镜头及其画布节点？'))return;current().shots=current().shots.filter(x=>x.id!==id);if(state.canvas[epId])state.canvas[epId]=state.canvas[epId].filter(n=>n.shotId!==id);save();$('#modal').close();render()}}
function editAsset(id){const existing=state.assets.find(a=>a.id===id),a=existing||{id:crypto.randomUUID(),name:'',kind:assetFilter!=='全部'&&assetCategories().includes(assetFilter)?assetFilter:'人物',image:'',traits:'',bio:'',description:'',voice:'',approval:'待确认'};let pendingImage=a.image,pendingSample=a.sample||'';openModal(`${modalTop(existing?a.name+' · 资产档案':'新建创作资产')}<div class="detail-grid"><div>${a.image?`<img class="detail-image" src="${src(a.image)}" alt="${esc(a.name)}">`:'<div class="empty">上传形象或场景参考</div>'}<label class="field">参考图片<input id="assetImage" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="assetImageState"></div><label class="field">形象确认状态<select id="assetApproval"><option ${a.approval==='待确认'?'selected':''}>待确认</option><option ${a.approval==='已确认'?'selected':''}>已确认</option></select></label><div class="notice">只有实际查看并认可形象后，再设为“已确认”。切换参考图将自动恢复待确认。</div><h3>人物声音档案</h3><label class="field">音色与审批记录<input id="assetVoice" value="${esc(a.voice)}" placeholder="平台、音色、版本和审批记录"></label>${a.sample?`<audio controls src="${src(a.sample)}"></audio>`:''}<label class="field">上传参考声音<input id="assetSample" type="file" accept="audio/*"></label><small class="muted">参考声音用于试听，不能当作整集正式配音。</small></div><div><label class="field">资产名称<input id="assetName" value="${esc(a.name)}"></label><label class="field">资产类型<select id="assetKind">${assetCategories().map(k=>`<option value="${esc(k)}" ${a.kind===k?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label class="field">外观与设定<textarea id="assetDesc">${esc(a.description)}</textarea></label><label class="field">性格特征（人物）<textarea id="assetTraits">${esc(a.traits)}</textarea></label><label class="field">人物小传 / 资产背景<textarea id="assetBio" style="min-height:150px">${esc(a.bio)}</textarea></label><p class="muted" style="font-size:11px">${esc(a.notes||'')} 档案修改会同步到所有关联镜头。</p></div></div><div class="dialog-footer"><button data-close>取消</button><button id="saveAsset" class="primary">保存资产档案</button></div>`);$('#assetImage').onchange=async ev=>{try{if(!ev.target.files[0])return;pendingImage=await readMedia(ev.target.files[0],'image');$('#assetApproval').value='待确认';$('#assetImageState').textContent='新参考图已选择 · 保存后生效'}catch(e){toast(e.message)}};$('#assetSample').onchange=async ev=>{try{if(!ev.target.files[0])return;pendingSample=await readMedia(ev.target.files[0],'audio');toast('声音样本已选择，保存后生效')}catch(e){toast(e.message)}};$('#saveAsset').onclick=()=>{const name=$('#assetName').value.trim();if(!name)return toast('请填写资产名称');Object.assign(a,{name,kind:$('#assetKind').value,description:$('#assetDesc').value,traits:$('#assetTraits').value,bio:$('#assetBio').value,voice:$('#assetVoice').value,approval:$('#assetApproval').value,image:pendingImage,sample:pendingSample});if(!existing)state.assets.push(a);save();$('#modal').close();render();toast('资产档案已保存')}}
async function readMedia(f,kind){if(f.size>25*1024*1024)throw Error('单个素材请小于25 MB');if(!f.type.startsWith(kind+'/')||(kind==='image'&&!/^image\/(png|jpeg|webp)$/.test(f.type)))throw Error('请选择有效的'+(kind==='image'?'PNG、JPEG或WebP图片':'音频文件'));return await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(f)})}
function splitShots(){const e=current();if(e.shots.length&&!confirm('重新拆分将替换本集镜头和画布。建议先导出备份。继续？'))return;const lines=e.script.split('\n').map(s=>s.trim()).filter(Boolean);let result=[],desc=[],dialogue=[],scene='',cast=[];function flush(){if(!desc.length&&!dialogue.length)return;let description=desc.join('\n');result.push({id:crypto.randomUUID(),title:(description.replace(/^【[^】]*】/,'').slice(0,16)||scene||'对白镜头'),duration:Math.min(15,Math.max(3,Math.ceil(dialogue.join('').length/4)||5)),description:scene+'\n'+description,dialogue:dialogue.join('\n')||'环境声与动作声',prompt:`米黄纸张质感，精细深灰手绘线条，柔和淡彩二维画面。${scene}。${description}\n人物：${cast.join('、')}。保持人物形象和相邻镜头动作连续。`,image:'',audio:'',assetIds:state.assets.filter(a=>cast.some(c=>c.includes(a.name)||a.name.includes(c))).map(a=>a.id)});desc=[];dialogue=[]}
for(const line of lines){if(/^第.+[集章]/.test(line))continue;if(/^\d+[-—]\d+/.test(line)){flush();scene=line;cast=[]}else if(/^人物[：:]/.test(line)){cast=line.replace(/^人物[：:]/,'').split(/[、，,]/)}else if(/^【(画面|动作|镜头)】/.test(line)){flush();desc.push(line)}else if(/^【/.test(line)){desc.push(line)}else if(/^[^：:]{1,25}[：:]/.test(line)){dialogue.push(line)}else{if(desc.join('').length>180)flush();desc.push(line)}}flush();if(!result.length)return toast('没有可拆分的内容，请先填写本集剧本');e.shots=result;delete state.canvas[e.id];save();tab='shots';render();toast('已拆分为 '+result.length+' 个分镜草稿，请检查节奏与台词')}
function syncCanvas(){let e=current();if(!e.shots.length){toast('请先拆分本集分镜');page='episodes';tab='script';render();return}const old=state.canvas[e.id]||[];state.canvas[e.id]=e.shots.flatMap((s,i)=>['image','prompt','audio'].map((type,j)=>old.find(n=>n.shotId===s.id&&n.type===type)||{id:s.id+'-'+type,shotId:s.id,type,x:35+j*345,y:35+i*340}));save();page='canvas';render();toast('本集关键帧、描述和配音卡片已带入画布')}
function bindPage(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-ep]').forEach(b=>b.onclick=()=>{epId=b.dataset.ep;render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$$('[data-edit-shot]').forEach(b=>{b.onclick=()=>editShot(b.dataset.editShot);b.onkeydown=ev=>{if(ev.key==='Enter')b.click()}});$$('[data-asset]').forEach(b=>{b.onclick=()=>editAsset(b.dataset.asset);b.onkeydown=ev=>{if(ev.key==='Enter')b.click()}});$$('[data-filter]').forEach(b=>b.onclick=()=>{assetFilter=b.dataset.filter;render()});on('#startProduction',syncCanvas);on('#syncCanvas',syncCanvas);on('#createBoard',syncCanvas);on('#splitScript',splitShots);on('#splitEmpty',splitShots);on('#addAsset',()=>editAsset());on('#addCategory',addAssetCategory);$$('[data-remove-category]').forEach(b=>b.onclick=()=>removeAssetCategory(b.dataset.removeCategory));on('#addShot',()=>{let s={id:crypto.randomUUID(),title:'新镜头',duration:5,description:'',dialogue:'',prompt:'',image:'',audio:'',assetIds:[]};current().shots.push(s);save();render();editShot(s.id)});on('#saveScript',()=>{current().script=$('#episodeScript').value;save();toast('剧本已保存，已有分镜保持原样')});on('#saveIntro',()=>{if(!$('#episodeTitle').value.trim())return toast('集名称不能为空');current().title=$('#episodeTitle').value.trim();current().summary=$('#episodeSummary').value;save();render();toast('本集介绍已保存')});on('#exportEpisode',()=>download('第'+current().number+'集_分镜与台词.json',JSON.stringify(current(),null,2)));on('#exportCanvas',()=>download('第'+current().number+'集_制作画布.json',JSON.stringify({episode:current(),nodes:state.canvas[epId]||[],assets:state.assets.filter(a=>current().shots.some(s=>s.assetIds.includes(a.id)))},null,2)));on('#arrange',()=>{if(!state.canvas[epId])return;state.canvas[epId].forEach(n=>{n.x=35+['image','prompt','audio'].indexOf(n.type)*345;n.y=35+current().shots.findIndex(s=>s.id===n.shotId)*340});save();render()});on('#zoomOut',()=>{zoom=Math.max(.4,zoom-.1);render()});on('#zoomIn',()=>{zoom=Math.min(1.5,zoom+.1);render()});if($('#canvasEpisode'))$('#canvasEpisode').onchange=ev=>{epId=ev.target.value;render()};if($('#assetSearch'))$('#assetSearch').oninput=ev=>{let pos=ev.target.selectionStart;query=ev.target.value;render();$('#assetSearch').focus();$('#assetSearch').setSelectionRange(pos,pos)};bindDrag();if(page==='source')bindImport()}
function on(s,fn){if($(s))$(s).onclick=fn}
function bindDrag(){$$('.node-head').forEach(h=>h.onpointerdown=ev=>{const node=h.parentElement,n=state.canvas[epId].find(x=>x.id===node.dataset.node),x=ev.clientX,y=ev.clientY,ox=n.x,oy=n.y;h.setPointerCapture(ev.pointerId);h.onpointermove=ev=>{n.x=Math.max(10,ox+(ev.clientX-x)/zoom);n.y=Math.max(10,oy+(ev.clientY-y)/zoom);node.style.left=n.x+'px';node.style.top=n.y+'px'};h.onpointerup=()=>{h.onpointermove=null;h.onpointerup=null;let v=$('.board-viewport'),left=v.scrollLeft,top=v.scrollTop;save();render();$('.board-viewport').scrollTo(left,top)}})}
function parseEpisodes(text,mode){let chunks=[];if(mode==='heading'){const re=/^\s*第[零〇一二三四五六七八九十百千万\d]+[集章][^\n]*$/gm;let matches=[...text.matchAll(re)];if(matches.length){if(text.slice(0,matches[0].index).trim())chunks.push({title:'序章',script:text.slice(0,matches[0].index).trim()});chunks.push(...matches.map((m,i)=>({title:m[0].trim().replace(/^第[零〇一二三四五六七八九十百千万\d]+[集章]\s*/, '')||'未命名',script:text.slice(m.index,matches[i+1]?.index||text.length).trim()})))}else chunks=[{title:'故事开篇',script:text}]}else{let part='';for(let p of text.split(/\n\s*\n/)){if(part.length+p.length>1500&&part){chunks.push({title:'篇章 '+(chunks.length+1),script:part});part=''}while(p.length>1800){if(part){chunks.push({title:'篇章 '+(chunks.length+1),script:part});part=''}chunks.push({title:'篇章 '+(chunks.length+1),script:p.slice(0,1500)});p=p.slice(1500)}part+=(part?'\n\n':'')+p}if(part)chunks.push({title:'篇章 '+(chunks.length+1),script:part})}return chunks.map((x,i)=>({...x,id:crypto.randomUUID(),number:i+1,summary:x.script.replace(/^.*\n/,'').trim().slice(0,90),shots:[]}))}
function bindImport(){let upload=async f=>{if(!f)return;if(!/\.(txt|md|markdown)$/i.test(f.name))return toast('请上传TXT或Markdown文本');if(f.size>10*1024*1024)return toast('文本文件请小于10 MB');$('#storyInput').value=await f.text();$('#fileName').textContent=f.name;if(!$('#newTitle').value)$('#newTitle').value=f.name.replace(/\.[^.]+$/,'')};$('#storyFile').onchange=ev=>upload(ev.target.files[0]);let drop=$('#dropzone');drop.ondragover=ev=>{ev.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=ev=>{ev.preventDefault();drop.classList.remove('drag');upload(ev.dataTransfer.files[0])};$('#importStory').onclick=()=>{let text=$('#storyInput').value.trim();if(!text)return toast('请先上传或粘贴故事文本');let eps=parseEpisodes(text,$('#splitMode').value),title=$('#newTitle').value.trim()||'未命名故事';openModal(`${modalTop('检查分集 · '+title)}<p>识别到 ${eps.length} 集，确认后建立新项目。当前项目会先自动下载一份备份。</p><div class="script" style="max-height:360px">${eps.map(e=>`<div class="panel"><b>第${e.number}集 ${esc(e.title)}</b><small> · ${e.script.length}字</small><p>${esc(e.summary)}</p></div>`).join('')}</div><div class="dialog-footer"><button data-close>返回修改</button><button class="primary" id="confirmImport">备份当前项目并导入</button></div>`);$('#confirmImport').onclick=()=>{exportProject();state={storyStyle:structuredClone(projectStyle()),title,subtitle:'新的漫剧计划',importedName:'用户导入 · '+new Date().toLocaleDateString(),episodes:eps,assets:[],canvas:{}};epId=eps[0].id;save();$('#modal').close();page='episodes';tab='script';render();toast('故事已导入，可以开始拆分镜头')}}}
function download(name,text){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportProject(){download(state.title+'_项目备份.json',JSON.stringify({format:'wanxiang-v1',state},null,2))}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('提示词已复制')}catch{openModal(modalTop('复制提示词')+`<textarea style="height:350px">${esc(text)}</textarea>`);$('#modal textarea').select()}}
function services(){openModal(`${modalTop('生成服务')}<p>当前为本地保存的交互预览版，已接入项目现有素材。新内容可通过外部生成平台制作，再回传到对应镜头。</p><div class="panel"><h3>分集与分镜</h3><span class="tag">可用</span><p>文本按章节拆集，剧本按场景和动作段落拆成可编辑草稿；当前不含AI改编模型。</p><h3>关键帧生成</h3><span class="tag">待接入</span><p>先确认资产形象，复制完整提示词到生成平台，完成后上传PNG / JPEG / WebP。</p><h3>角色配音合成</h3><span class="tag">待接入</span><p>已收录人物音色参考。当前可上传、试听并关联正式音频，尚未连接Qwen3-TTS运行服务。</p></div><p class="muted">内容保存在当前浏览器；换设备前请导出项目备份。</p>`)}
$$('#navigation button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#projectName').onclick=()=>go('source');$('#services').onclick=services;$('#exportProject').onclick=exportProject;$('#restore').onchange=async ev=>{try{let f=ev.target.files[0];if(!f)return;let data=JSON.parse(await f.text());if(data.format!=='wanxiang-v1'||!Array.isArray(data.state?.episodes)||!data.state.episodes.length||!Array.isArray(data.state.assets)||!data.state.canvas||!data.state.episodes.every(e=>typeof e.id==='string'&&typeof e.title==='string'&&typeof e.script==='string'&&Array.isArray(e.shots)&&e.shots.every(s=>typeof s.id==='string'&&typeof s.title==='string'&&typeof s.description==='string'&&typeof s.dialogue==='string'&&Number.isFinite(s.duration)&&s.duration>0&&Array.isArray(s.assetIds)))||!data.state.assets.every(a=>typeof a.name==='string'&&typeof a.id==='string'))throw Error('不是有效的万象项目备份');if(!confirm('恢复备份将替换当前项目。继续？'))return;exportProject();state=data.state;epId=state.episodes[0].id;save();render();toast('项目备份已恢复')}catch(e){toast('恢复失败：'+e.message)}ev.target.value=''};init();
